import { Integration, ClientIntegrationType } from './types'
import { isUUID } from 'validator'

export enum TagType {
	COMPONENT = 'component',
	PAGE = 'page',
	EXPO_PAGE = 'expo-page',
	DATABASE = 'database',
	CLIENT_INTEGRATION = 'client_integration',
	CUSTOM_INTEGRATION = 'custom_integration',
	INTEGRATION = 'integration',
	PROJECT_GROUP_TO_FORK = 'project_group_to_fork',
	DATA_STORE = 'data_store',
	ASSET = 'asset',
	FUNCTION = 'function'
}

export type TagsStoredInReferences = Omit<
	TagType,
	TagType.INTEGRATION | TagType.PROJECT_GROUP_TO_FORK
>

export const isEnumValue = <T extends Record<string, string>>(
	value: string,
	enumType: T
): value is T[keyof T] => Object.values(enumType).includes(value)

export const asEnumValue = <T extends Record<string, string>>(
	value: string,
	enumType: T
): T[keyof T] | undefined => {
	if (!isEnumValue(value, enumType)) {
		return undefined
	}
	return value
}

export const getTagValidation = (tag: TagType) => {
	switch (tag) {
		case TagType.DATA_STORE:
		case TagType.ASSET:
		case TagType.FUNCTION:
		case TagType.COMPONENT:
		case TagType.PAGE:
		case TagType.EXPO_PAGE:
		case TagType.DATABASE:
		case TagType.CUSTOM_INTEGRATION:
		case TagType.PROJECT_GROUP_TO_FORK:
			return { type: 'uuid', validate: isUUID }
		case TagType.INTEGRATION:
			return {
				type: 'enum',
				validate: (value: string) => isEnumValue(value, Integration)
			}
		case TagType.CLIENT_INTEGRATION:
			return {
				type: 'enum',
				validate: (value: string) => isEnumValue(value, ClientIntegrationType)
			}
		default: {
			const exhaustiveCheck: never = tag
			return exhaustiveCheck
		}
	}
}

const UUID_REGEX_PART =
	'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}'

const getTagsOfTypeFromMarkdown = ({
	markdown,
	type
}: {
	markdown: string
	type: TagType | 'design_system'
}) => {
	const regex = new RegExp(`{${type}:(${UUID_REGEX_PART})}`, 'g')
	const ids: string[] = []
	let match = regex.exec(markdown)
	while (match?.length) {
		const [, value] = match
		if (value) {
			ids.push(value)
		}
		match = regex.exec(markdown)
	}
	return [...new Set(ids)]
}

const getLabelsOfTypeFromMarkdown = ({
	markdown,
	type
}: {
	markdown: string
	type: TagType
}) => {
	const regex = new RegExp(`{${type}:([^}]*)}`, 'g')
	const ids: string[] = []
	let match = regex.exec(markdown)
	while (match?.length) {
		const [, value] = match
		if (value) {
			ids.push(value)
		}
		match = regex.exec(markdown)
	}
	return ids
}

