export const getMarkdownRegexesForTag = ({ type }: { type: TagType }) => {
	let importRegExp: RegExp
	let regExp: RegExp
	if (getTagValidation(type).type === 'uuid') {
		importRegExp = new RegExp(`{${type}:(${UUID_REGEX_PART})}`)
		regExp = new RegExp(`{${type}:(${UUID_REGEX_PART})}$`)
	} else {
		importRegExp = new RegExp(`{${type}:([^}]*)}`)
		regExp = new RegExp(`{${type}:([^}]*)}$`)
	}

	return { importRegExp, regExp }
}

export const isIntegration = (value: string): value is Integration =>
	Object.values(Integration).includes(value as Integration)

export const getIntegrationsFromPrompt = (prompt: string) => {
	const integrations: Integration[] = []

	const integrationRegex = /{integration:([a-zA-Z0-9_]+)}/g
	let [, match] = integrationRegex.exec(prompt) ?? []
	while (match) {
		if (isIntegration(match)) {
			integrations.push(match)
		}
		;[, match] = integrationRegex.exec(prompt) ?? []
	}
	return [...new Set(integrations)]
}
